"use strict";

/**
 * Test the 55 p57 interior totients as per-page p56 prime-start ordinals.
 *
 * Node.js 22, CommonJS, no dependencies.
 * Run: node sims/lp2_parable55_totient_page_key_schedule_gate.cjs
 *
 * Two fixed assignments are tested:
 * A. p57 interior totients in physical LP2 page order (p0..p55, excluding p50).
 * B. p57 interior totients in the Josephus page order generated by those same
 *    totients, with the 55th value assigned to the 55th eliminated page.
 *
 * The established p56 cipher's transparent-F constraint is enforced with
 * exhaustive branch tracking. The p56 known-answer vector is a positive
 * control. No phase search or language scoring is used.
 */
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const read = file => fs.readFileSync(path.join(root, file), "utf8");
const corpus = JSON.parse(read("resources/liber-primus/lp2-corpus.json"));
const transcription = read("resources/lp2-transcription.txt");
const segments = transcription.split(/^\s*%\s*$/m);
assert.equal(segments.length, 57);

const runeToIndex = new Map(corpus.runes.map((r, i) => [r, i]));
const runeTokens = corpus.translit.map((token, index) => ({token, index}))
  .sort((a, b) => b.token.length - a.token.length);
const mod29 = n => ((n % 29) + 29) % 29;

function parseWords(segment) {
  return (segment.replace(/\/\s*/gu, "").match(/[\u16A0-\u16FF]+/gu) || [])
    .map(word => Array.from(word, rune => {
      const index = runeToIndex.get(rune);
      assert.notEqual(index, undefined, "unknown original GP rune");
      return index;
    }));
}

function encodeWord(word) {
  const normalized = word.toUpperCase()
    .replace(/QU/g, "CW")
    .replace(/V/g, "U")
    .replace(/K/g, "C")
    .replace(/Z/g, "S")
    .replace(/ING/g, "NG")
    .replace(/IO/g, "IA");
  const output = [];
  for (let i = 0; i < normalized.length;) {
    const token = runeTokens.find(x => normalized.startsWith(x.token, i));
    assert.ok(token, "known plaintext token cannot be represented: " + normalized);
    output.push(token.index);
    i += token.token.length;
  }
  return output;
}

function primes(count) {
  let limit = 10000;
  while (true) {
    const composite = new Uint8Array(limit + 1);
    const output = [];
    for (let p = 2; p <= limit; p++) {
      if (composite[p]) continue;
      output.push(p);
      if (p * p <= limit) {
        for (let k = p * p; k <= limit; k += p) composite[k] = 1;
      }
    }
    if (output.length >= count) return output.slice(0, count);
    limit *= 2;
  }
}
const primeList = primes(5000);
const totients = primeList.map(p => p - 1);

function josephus(stepValues) {
  const remaining = Array.from({length: 56}, (_, i) => i);
  const eliminated = [];
  let cursor = 0;
  for (const step of stepValues) {
    cursor = (cursor + step - 1) % remaining.length;
    eliminated.push(remaining.splice(cursor, 1)[0]);
  }
  return {eliminated, survivors: remaining};
}

function firstImpossible(page, startOrdinal) {
  const ciphertext = corpus.pages[page].indices;
  let states = new Set([0]);
  for (let i = 0; i < ciphertext.length; i++) {
    const c = ciphertext[i];
    const next = new Set();
    const cases = [];
    for (const used of states) {
      if (c === 0) {
        next.add(used);
        cases.push({used, mode: "literal-F", nextUsed: used});
      }
      const keyIndex = startOrdinal + used;
      const keyTotient = totients[keyIndex];
      const keyMod29 = keyTotient % 29;
      const plaintext = mod29(c - keyMod29);
      if (plaintext !== 0) {
        next.add(used + 1);
        cases.push({used, mode: "consume", keyIndex,
          prime: primeList[keyIndex], keyTotient, keyMod29,
          plaintext, nextUsed: used + 1});
      } else {
        cases.push({used, mode: "invalid-consume", keyIndex,
          prime: primeList[keyIndex], keyTotient, keyMod29, plaintext});
      }
    }
    if (next.size === 0) {
      const prefix = ciphertext.slice(0, i + 1);
      return {
        page, startOrdinal, failAt: i, cipher: c,
        cipherRune: corpus.translit[c],
        statesBefore: [...states].sort((a, b) => a - b),
        cases,
        prefix: prefix.map(x => corpus.translit[x]).join(""),
        prefixLiteralFPositions: prefix.flatMap((x, j) => x === 0 ? [j] : [])
      };
    }
    states = next;
  }
  return {page, startOrdinal, valid: true, finalStates: [...states]};
}

// Verify all 55 original nonempty pages; p50 is the runeless survivor.
const pages = [];
for (let page = 0; page < 56; page++) {
  if (page === 50) {
    assert.equal(corpus.pages[page].indices.length, 0);
    continue;
  }
  const segmentIndex = page < 50 ? page : page - 1;
  assert.deepEqual(parseWords(segments[segmentIndex]).flat(), corpus.pages[page].indices);
  pages.push(page);
}
assert.equal(pages.length, 55);

// The 20 p57 words yield exactly 55 interior rune values.
const p57Words = parseWords(segments[56]);
assert.equal(p57Words.length, 20);
assert.deepEqual(p57Words.flat(), corpus.pages[57].indices);
const interiors = p57Words.flatMap(word => word.slice(1, -1));
assert.equal(interiors.length, 55);
const keyStarts = interiors.map(index => corpus.prime[index] - 1);
const route = josephus(keyStarts);
assert.deepEqual(route.survivors, [50]);
assert.deepEqual([...route.eliminated].sort((a, b) => a - b), pages);

// A: assign the i-th totient directly to the i-th physical page.
const physical = pages.map((page, i) => firstImpossible(page, keyStarts[i]));

// B: assign the i-th totient to the i-th page eliminated by the same
// Josephus route. This couples the proposed page order and key-start list.
const josephusAssigned = route.eliminated.map((page, i) =>
  firstImpossible(page, keyStarts[i]));

const physicalFailures = physical.filter(result => !result.valid);
const physicalPasses = physical.filter(result => result.valid).map(result => result.page);
const josephusFailures = josephusAssigned.filter(result => !result.valid);
const josephusPasses = josephusAssigned.filter(result => result.valid).map(result => result.page);

assert.equal(physicalFailures.length, 53);
assert.deepEqual(physicalPasses, [49, 55]);
assert.equal(josephusFailures.length, 54);
assert.deepEqual(josephusPasses, [42]);

const p0 = physical.find(result => result.page === 0);
assert.equal(keyStarts[0], 96);
assert.equal(p0.failAt, 0);
assert.equal(p0.cipher, 15);
assert.equal(p0.cases[0].keyIndex, 96);
assert.equal(p0.cases[0].prime, 509);
assert.equal(p0.cases[0].keyTotient, 508);
assert.equal(p0.cases[0].keyMod29, 15);
assert.equal(p0.cases[0].plaintext, 0);

const p39 = josephusAssigned.find(result => result.page === 39);
assert.equal(route.eliminated[0], 39);
assert.equal(p39.startOrdinal, 96);
assert.equal(p39.failAt, 0);
assert.equal(p39.cipher, 15);
assert.equal(p39.cases[0].keyIndex, 96);
assert.equal(p39.cases[0].prime, 509);
assert.equal(p39.cases[0].keyTotient, 508);
assert.equal(p39.cases[0].keyMod29, 15);
assert.equal(p39.cases[0].plaintext, 0);

// Positive control: the known p56 plaintext re-encodes to its exact ciphertext.
const p56Plaintext =
  "AN END WITHIN THE DEEP WEB THERE EXISTS A PAGE THAT HASHES TO IT " +
  "IS THE DUTY OF EUERY PILGRIM TO SEEC OUT THIS PAGE";
const p56Plain = p56Plaintext.split(/\s+/).flatMap(encodeWord);
assert.equal(p56Plain.length, 85);
const literalF = p56Plain.flatMap((r, i) => r === 0 ? [i] : []);
assert.deepEqual(literalF, [56]);
let consumed = 0;
const p56Cipher = p56Plain.map(plain => {
  if (plain === 0) return 0;
  const cipher = mod29(plain + totients[consumed] % 29);
  consumed++;
  return cipher;
});
assert.deepEqual(p56Cipher, corpus.pages[56].indices);
assert.equal(consumed, 84);

console.log(JSON.stringify({
  decision: "REJECTED: p57 interior totients as per-page p56 prime-start ordinals",
  p57: {
    wordCount: p57Words.length,
    interiorCount: interiors.length,
    first12KeyStarts: keyStarts.slice(0, 12),
    maximumKeyStart: Math.max(...keyStarts),
    josephusFirst12Pages: route.eliminated.slice(0, 12),
    survivor: route.survivors
  },
  p56PositiveControl: {
    plaintextRunes: p56Plain.length,
    literalFPositions: literalF,
    keySymbolsConsumed: consumed,
    exactOriginalCiphertextReproduced: true
  },
  physicalPageAssignment: {
    failures: physicalFailures.length,
    passes: physicalPasses,
    firstFailures: physical.slice(0, 12)
  },
  josephusPageAssignment: {
    failures: josephusFailures.length,
    passes: josephusPasses,
    firstFailures: josephusAssigned.slice(0, 12)
  },
  scope: [
    "Tests the p57 interior totient values themselves as page-specific prime-start ordinals.",
    "Tests physical page order and the Josephus order generated by the same totients.",
    "Does not test or reject a different, independently selected consumer for the p57 sequence."
  ]
}, null, 2));
